# ── Catalogue accessor ─────────────────────────────────────

CATALOGUE = {
    "oak":   (OAK_VERTICES,   OAK_FACES),
    "pine":  (PINE_VERTICES,  PINE_FACES),
    "apple": (APPLE_VERTICES, APPLE_FACES),
    "bush":  (BUSH_VERTICES,  BUSH_FACES),
}


def classify_tree(canopy_height_m: float) -> str:
    """Classify a tree type by canopy height.

    - > 12m → oak (broad deciduous)
    - 6-12m → pine (conifer)
    - 3-6m  → apple (small deciduous)
    - < 3m  → bush
    """
    if canopy_height_m > 12:
        return "oak"
    if canopy_height_m > 6:
        return "pine"
    if canopy_height_m > 3:
        return "apple"
    return "bush"


def get_scaled_mesh(
    tree_type: str,
    target_height_m: float,
    position_x_mm: float = 0.0,
    position_y_mm: float = 0.0,
    ground_z_mm: float = 0.0,
) -> tuple[list[tuple[float, float, float]], list[tuple[int, int, int]]]:
    """Get a tree mesh scaled to target height and positioned.

    Returns (vertices_mm, faces) ready for lite-step Mesh.
    Vertices are in mm (lite-step script convention), Z-up.

    Coordinate mapping from catalogue (X=east, Y=up, Z=south)
    to lite-step (X=east, Y=north, Z=up):
      catalogue X → lite-step X
      catalogue Y → lite-step Z (up)
      catalogue Z → lite-step -Y (north = -south)
    """
    verts, faces = CATALOGUE[tree_type]
    template_h = HEIGHTS[tree_type]
    scale = target_height_m / template_h

    # Scale to mm and remap axes
    s_mm = scale * 1000.0
    mapped_verts: list[tuple[float, float, float]] = []
    for v in verts:
        x = v[0] * s_mm + position_x_mm   # east
        y = -v[2] * s_mm + position_y_mm   # north (negate south)
        z = v[1] * s_mm + ground_z_mm      # up
        mapped_verts.append((x, y, z))

    mapped_faces = [(f[0], f[1], f[2]) for f in faces]
    return mapped_verts, mapped_faces
